#!/usr/bin/env python3
"""Single-file variant: many small functions repeating the same subtype checks.
Usage: gen.py <functions> <out.bal>"""
import sys
n, out = int(sys.argv[1]), sys.argv[2]
hdr = """import ballerina/io;

type R1 record {| int a; string b; decimal c?; int[] d; |};
type R2 record { int a; string b; decimal c?; int[] d; };
type Pt record {| int x; int y; |};
"""
body = """
function f{i}(R1 r, int[] xs) returns int {{
    R2 s = r;
    json j = r;
    anydata ad = s;
    map<anydata> m = s;
    Pt p = {{x: {i}, y: xs.length()}};
    record {{| int x; int y; |}} q = p;
    function (int) returns int g = x => x + {i};
    int total = g(xs.length());
    foreach int x in xs {{
        if x > total {{
            total += x;
        }}
    }}
    return total + (j is map<json> ? 1 : 0) + (ad is R1 ? 1 : 0) + m.length() + (q is Pt ? 1 : 0);
}}
"""
with open(out, "w") as f:
    f.write(hdr)
    for i in range(n):
        f.write(body.format(i=i))
    f.write("\npublic function main() {\n    R1 r = {a: 1, b: \"x\", d: [1, 2]};\n    int t = 0;\n")
    for i in range(0, n, max(1, n // 10)):
        f.write(f"    t += f{i}(r, [1, 2, 3]);\n")
    f.write("    io:println(t);\n}\n")

# --- multi-module variant gen_pkg.py ---
#!/usr/bin/env python3
"""Generate a multi-module Ballerina package with many small functions whose bodies
repeat the same subtype checks (record/json/anydata/function-type assignability).
Usage: gen_pkg.py <out_dir> <modules> <functions_per_module>"""
import os, sys
out, nmods, nfns = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
os.makedirs(out, exist_ok=True)
open(os.path.join(out, "Ballerina.toml"), "w").write(
    '[package]\norg = "perf"\nname = "manyfns"\nversion = "0.1.0"\n')
types = """
public type R1 record {| int a; string b; decimal c?; int[] d; |};
public type R2 record { int a; string b; decimal c?; int[] d; };
public type Pt record {| int x; int y; |};
"""
body = """
public function f{i}(R1 r, int[] xs) returns int {{
    R2 s = r;
    json j = r;
    anydata ad = s;
    map<anydata> m = s;
    Pt p = {{x: {i}, y: xs.length()}};
    record {{| int x; int y; |}} q = p;
    function (int) returns int g = x => x + {i};
    int total = g(xs.length());
    foreach int x in xs {{
        if x > total {{
            total += x;
        }}
    }}
    return total + (j is map<json> ? 1 : 0) + (ad is R1 ? 1 : 0) + m.length() + (q is Pt ? 1 : 0);
}}
"""
for k in range(nmods):
    d = os.path.join(out, "modules", f"mod{k}")
    os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, f"mod{k}.bal"), "w") as f:
        f.write(types)
        for i in range(nfns):
            f.write(body.format(i=i))
with open(os.path.join(out, "main.bal"), "w") as f:
    f.write("import ballerina/io;\n")
    for k in range(nmods):
        f.write(f"import perf/manyfns.mod{k};\n")
    f.write("\npublic function main() {\n    int t = 0;\n")
    for k in range(nmods):
        f.write(f"    mod{k}:R1 r{k} = {{a: 1, b: \"x\", d: [1, 2]}};\n")
        f.write(f"    t += mod{k}:f0(r{k}, [1, 2, 3]) + mod{k}:f{nfns-1}(r{k}, [4]);\n")
    f.write("    io:println(t);\n}\n")

